Bash(# Batch fix: Add tags to all AIMart docs \(they all need the same aimart tag\)
for f in "E:/知识库/05_AIMart_AI项目/aimart/docs/"*.md; do
  name=$\(basename "$f" .md\)
  # Generate appropriate tags based on filename
  case "$name" in
    AIMart_Whitepaper\) tags="aimart, whitepaper, ai, trading" ;;
    AIMart_Capability\) tags="aimart, capability, schema" ;;
    AIMart_Constraints\) tags="aimart, constraints, rules" ;;
    AIMart_Boundary\) tags="aimart, boundary, scope" ;;
    AIMart_Config\) tags="aimart, config, system" ;;
    AIMart_Audit\) tags="aimart, audit, security" ;;
    AIMart_Exec_01_Skeleton\) tags="aimart, architecture, skeleton" ;;
    AIMart_Exec_02_RulesEngine\) tags="aimart, rules-engine" ;;
    AIMart_Exec_03_AgentCardValidator\) tags="aimart, agent-card, validator" ;;
    AIMart_Exec_04_AuditLog\) tags="aimart, audit-log" ;;
    AIMart_Exec_05_CoreAPI\) tags="aimart, api, backend" ;;
    AIMart_Exec_06_Payment\) tags="aimart, payment, settlement" ;;
    AIMart_Exec_07_Auth\) tags="aimart, auth, security" ;;
    AIMart_Exec_08_SearchProtocol\) tags="aimart, search, protocol" ;;
    *\) tags="aimart" ;;
  esac
  # Add tags: line after the first --- line
  sed -i "0,/^---/a\\\\tags: [$tags]" "$f" 2>/dev/null
done
echo "AIMart docs: tags added")

